import math

def gradient(weights, x, y):
    if not x:
        return [0.0] * len(weights)
    return [
        2.0 * sum(
            (sum(a * b for a, b in zip(row, weights)) - target) * row[j]
            for row, target in zip(x, y)
        ) / len(x)
        for j in range(len(weights))
    ]

def step(weights, velocity, g, lr, momentum, clip):
    if clip < 0:
        raise ValueError('clip')
    norm = math.sqrt(sum(value * value for value in g))
    if norm == 0 or clip == 0:
        clipped = [0.0] * len(g)
    elif norm > clip:
        scale = clip / norm
        clipped = [value * scale for value in g]
    else:
        clipped = list(g)
    new_velocity = [momentum * old + grad for old, grad in zip(velocity, clipped)]
    new_weights = [weight - lr * vel for weight, vel in zip(weights, new_velocity)]
    return new_weights, new_velocity

from core import gradient, step

def solve(p):
    if p['clip'] < 0:
        raise ValueError('clip')
    weights = list(p['weights'])
    velocity = list(p['velocity'])
    for batches in p['steps']:
        total_samples = sum(len(batch['x']) for batch in batches)
        if total_samples == 0:
            continue
        accumulated = [0.0] * len(weights)
        for batch in batches:
            sample_count = len(batch['x'])
            if sample_count == 0:
                continue
            batch_gradient = gradient(weights, batch['x'], batch['y'])
            for index, value in enumerate(batch_gradient):
                accumulated[index] += value * sample_count
        mean_gradient = [value / total_samples for value in accumulated]
        weights, velocity = step(
            weights, velocity, mean_gradient, p['lr'], p['momentum'], p['clip']
        )
    return {'weights': weights, 'velocity': velocity}
